// Package assetclass is the Go mirror of the asset class taxonomy defined in
// standards/asset-classes.yaml (ADR-0002 D2).
//
// The hierarchy itself lives in classes_gen.go and the per-class attribute
// schemas in attribute_schemas_gen.json, both generated by
// scripts/generate-asset-classes.mjs and both checked for drift by
// `make audit`. This file is the hand-written half: the accessor over the
// embedded schemas.
//
// What belongs where:
//
//   - The BASE attributes of an asset (hostname, environment, owner, tags,
//     status, risk …) are columns of the assets table. They are not in these
//     schemas and never will be.
//   - CLASS-SPECIFIC attributes live in assets.attributes jsonb and are
//     validated against the effective schema returned here.
//   - Certificates, keys and crypto configurations are NOT class attributes.
//     They are posture objects with their own tables and their own lifecycles
//     (ADR-0002 D2).
package assetclass

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"strings"
	"sync"
)

//go:embed attribute_schemas_gen.json
var attributeSchemasJSON []byte

// AttributeProperty is one class-specific attribute: a JSON-schema property
// restricted to the shapes the registry allows (string / integer / number /
// boolean / array-of-scalar, optionally with a string enum).
type AttributeProperty struct {
	Type        string   `json:"type"`
	Description string   `json:"description,omitempty"`
	Enum        []string `json:"enum,omitempty"`
	Items       *struct {
		Type string `json:"type"`
	} `json:"items,omitempty"`
}

// AttributeSchema is the effective JSON-schema fragment for a class: its own
// attributes merged over every ancestor's. AdditionalProperties is always
// false — an attribute nothing declared is a collection bug, not a bonus.
type AttributeSchema struct {
	Type                 string                       `json:"type"`
	AdditionalProperties bool                         `json:"additionalProperties"`
	Properties           map[string]AttributeProperty `json:"properties"`
}

type schemaFile struct {
	Schemas map[string]json.RawMessage `json:"schemas"`
}

var (
	schemasOnce sync.Once
	rawSchemas  map[string]json.RawMessage
	schemas     map[string]AttributeSchema
	schemasErr  error
)

func loadSchemas() {
	schemasOnce.Do(func() {
		var f schemaFile
		if err := json.Unmarshal(attributeSchemasJSON, &f); err != nil {
			schemasErr = fmt.Errorf("assetclass: attribute_schemas_gen.json is not parseable: %w", err)
			return
		}
		rawSchemas = f.Schemas
		schemas = make(map[string]AttributeSchema, len(f.Schemas))
		for key, raw := range f.Schemas {
			var s AttributeSchema
			if err := json.Unmarshal(raw, &s); err != nil {
				schemasErr = fmt.Errorf("assetclass: schema for %q is not parseable: %w", key, err)
				return
			}
			schemas[key] = s
		}
	})
}

// Schema returns the effective attribute schema for a class — its own
// attributes plus every ancestor's. The second result is false for an unknown
// key; a class with no class-specific attributes returns a schema with an
// empty Properties map, which is not the same thing.
//
// It panics only if the embedded file is unparseable, which a build cannot
// produce: the generator writes it and TestEmbeddedSchemas covers it.
func Schema(key string) (AttributeSchema, bool) {
	loadSchemas()
	if schemasErr != nil {
		panic(schemasErr)
	}
	s, ok := schemas[key]
	if !ok {
		return s, false
	}
	// Hand back a copy of the property map: the cache is process-wide and a
	// caller that mutated the shared map would corrupt every later reader.
	out := s
	out.Properties = make(map[string]AttributeProperty, len(s.Properties))
	for k, v := range s.Properties {
		out.Properties[k] = v
	}
	return out, true
}

// SchemaJSON returns the same fragment as raw JSON, for callers handing it to
// a JSON-schema validator or storing it verbatim.
func SchemaJSON(key string) (json.RawMessage, bool) {
	loadSchemas()
	if schemasErr != nil {
		panic(schemasErr)
	}
	s, ok := rawSchemas[key]
	return s, ok
}

// Attributes returns the names and definitions of the class-specific
// attributes a class accepts, inherited ones included.
func Attributes(key string) (map[string]AttributeProperty, bool) {
	s, ok := Schema(key)
	if !ok {
		return nil, false
	}
	return s.Properties, true
}

// legacyAssetTypeClass maps each value of the retired public.asset_type enum
// onto the class an intake carrying that value should be hinted with.
//
// The reverse of Class.LegacyAssetType is many-to-one, so it cannot be derived:
// ten classes map to "appliance" and four to "endpoint". The rule applied here
// is the SHALLOWEST class that honestly covers the legacy value, never a more
// specific guess — the old enum could not tell a firewall from a printer, and
// inventing that distinction at import time would make a guess indistinguishable
// from a measurement, which ADR-0002 D4 ranks it above for good.
//
//   - "server"    → server.      The one value that named a real class.
//   - "endpoint"  → computer.    It is a computer; which kind is not known.
//   - "appliance" → hardware.    Network gear, printers and OT all arrived here.
//   - "service"   → application. `service` proper is DECLARED, never discovered
//     (ADR-0002 D2), so a discovered "service" is an application.
var legacyAssetTypeClass = map[string]Key{
	"server":    KeyServer,
	"endpoint":  KeyComputer,
	"appliance": KeyHardware,
	"service":   KeyApplication,
}

// FromLegacyAssetType maps a value of the retired asset_type enum onto a class
// key. The second result is false for anything else, INCLUDING the empty string:
// "no opinion" is a real answer and must not be turned into `server`, which is
// what the old ingest defaulted to for every finding that did not say.
func FromLegacyAssetType(legacy string) (Key, bool) {
	k, ok := legacyAssetTypeClass[strings.ToLower(strings.TrimSpace(legacy))]
	return k, ok
}
